{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 경형자동차 주차요금 할인이 일반 건물 주차장에도 모두 적용되는지",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제2호는 경형자동차에 대해 주차요금의 100분의 50을 할인할 수 있도록 정하고 있으나, 이는 시장이 설치한 공영주차장(노상·노외주차장)의 주차요금 감면에 관한 규정이다. 시·자치구 및 그 소속기관 청사에 부설된 주차장의 관리자는 제23조의2제1호에 따라 제7조제1항에 따른 감면 차량에 대해 감면할 수 있지만, 그 적용 대상은 제7조제1항에 따른 주차요금으로 한정된다. 따라서 이 조례만으로는 일반 건물 주차장 등 그 밖의 주차장까지 경차 할인이 모두 적용된다고 볼 수 없다.",
          "b_ids": "주차장:제7조제1항제2호, 주차장:제23조의2, 주차장:제23조의2제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
